import * as THREE from 'three';
import {HOUSE_IDS,HOME_ZONES,HOME_DOORS,HOME_CORRIDORS,houseWalls,HOUSE_CAMERA} from './layout.js';
import {ROOMS} from '../world/rooms.js';import {zoneBounds,collisionFor} from '../world/connected-layout.js';import {toWorld,worldTarget} from '../world/coordinates.js';
import {buildRoom} from '../world/builders.js';import {createToyKit,disposeToyTree} from '../world/toy-kit.js';import {signLabel} from '../world/handwriting.js';
export function buildHouseWorld(progress){
 const root=new THREE.Group();root.name='world.house';const shell=new THREE.Group();shell.name='house.shell';root.add(shell);const {box}=createToyKit(shell),zones=new Map(),walls=[],lowerWalls=[],floorGroups=[],world=collisionFor('house',ROOMS);let active='home',disposed=false;
 for(const id of HOUSE_IDS){const zone=HOME_ZONES[id],v=buildRoom(ROOMS[id],progress,{shell:false,portals:false});v.root.position.set(zone.x,0,zone.z);root.add(v.root);zones.set(id,v);}
 const patches=HOUSE_IDS.map(id=>({...zoneBounds(id),id})).concat(HOME_CORRIDORS.map(b=>({...b,id:'home.corridor'})));
 for(const b of patches){const group=new THREE.Group();group.userData.houseZone=b.id;shell.add(group);floorGroups.push(group);const floor=box(b.maxX-b.minX,.30,b.maxZ-b.minZ,b.id==='home.corridor'?'#dac9a8':'#ead7b9',(b.minX+b.maxX)/2,-.14,(b.minZ+b.maxZ)/2,.015,group);floor.name=b.id+'.connected-floor';for(let x=b.minX+.55;x<b.maxX-.1;x+=1.1)box(.016,.006,b.maxZ-b.minZ-.12,'#d6c2a3',x,.015,(b.minZ+b.maxZ)/2,.001,group);}
 for(const w of houseWalls()){const lower=box(w.hx*2,.6,w.hz*2,'#c7c8af',w.x,.3,w.z,.02);lower.userData=w;lowerWalls.push(lower);const upper=box(w.hx*2,2.05,w.hz*2,'#ece4d1',w.x,1.625,w.z,.025);upper.userData=w;walls.push(upper);}
 const tops=[];for(const d of HOME_DOORS.concat({id:'exit',x:5.425,z:14.375,color:'#bd9c79'})){const g=new THREE.Group();g.name='house.open-door.'+d.id;g.position.set(d.x,0,d.z);shell.add(g);const half=d.id==='exit'?1.22:1.59;for(const x of [-half,half])box(.15,2.55,.23,d.color,x,1.275,0,.025,g);const top=box(half*2+.15,.18,.23,d.color,0,2.61,0,.025,g),faces=[top];box(half*2-.15,.022,.38,d.color,0,.024,0,.01,g);for(const side of [-1,1]){const l=signLabel(d.id==='exit'?'마을 광장':d.id==='home'?'도름이의 침실':ROOMS[d.id].label,0,2.64,.129*side,half*1.65,'#4b655a','#fff4db',g);if(l){if(side<0)l.rotation.y=Math.PI;faces.push(l);}}tops.push({at:d,faces,group:g});}
 const api={root,worldId:'house',camera:HOUSE_CAMERA,zones,stars:[],occluders:walls,getZoneView:id=>zones.get(id),setActiveZone:id=>{active=id;},getActiveZone:()=>active,collisionWorld:()=>world,
 interactionWorld(id=active){return {...world,portals:ROOMS[id].portals.filter(p=>p.mode!=='walk').map(t=>worldTarget(id,t)),interactables:ROOMS[id].interactables.map(t=>worldTarget(id,t))};},
 updateVisibility(camera,player,{focusRoom=null}={}){const focus=HOUSE_IDS.includes(focusRoom)?focusRoom:null;for(const group of floorGroups)group.visible=!focus||group.userData.houseZone===focus;for(const lower of lowerWalls)lower.visible=!focus||lower.userData.zone===focus;const dx=camera.position.x-player.x,dz=camera.position.z-player.z,len=Math.hypot(dx,dz)||1;for(const w of walls){const a=w.userData;w.visible=(!focus||a.zone===focus)&&(dx*a.nx+dz*a.nz)*((w.position.x-player.x)*a.nx+(w.position.z-player.z)*a.nz)<=.01;}for(const t of tops){t.group.visible=!focus||t.at.id===focus;const x=t.at.x-player.x,z=t.at.z-player.z,along=(x*dx+z*dz)/len,across=Math.abs(x*dz-z*dx)/len;for(const m of t.faces)m.visible=!(along>0&&along<6&&across<2.3);}for(const [id,v]of zones){v.root.visible=!focus||id===focus;for(const prop of v.root.getObjectByName(id+'.cozy')?.children??[]){const n=prop.userData.wallNormal;if(n)prop.visible=dx*n[0]+dz*n[1]>=-.01;}for(const o of v.occluders)o.visible=camera.position.x-player.x>.6;}},
 animate(dt){for(const v of zones.values())v.animate?.(dt);},updateDiscoveries(ids){for(const v of zones.values())v.updateDiscoveries?.(ids);},updateGarden(g){for(const v of zones.values())v.updateGarden?.(g);},updateDecorations(p){zones.get('home').updateDecorations(p);},
 dispose(){if(disposed)return;disposed=true;for(const v of zones.values())v.dispose();disposeToyTree(shell);root.removeFromParent();root.clear();}
 };api.residents={snapshot:()=>[],collisionWorld:()=>world,interactions:()=>[]};return api;
}
